# Restaurant ops prototype: simple table orders + daily sales summary for small restaurants
from dataclasses import dataclass, field
from datetime import date

@dataclass
class Order:
    table: int
    items: dict  # name -> (qty, price)
    closed: bool = False

    def total(self):
        return sum(q * p for q, p in self.items.values())

@dataclass
class Day:
    day: date = field(default_factory=date.today)
    orders: list = field(default_factory=list)

    def open_order(self, table, items):
        o = Order(table, items)
        self.orders.append(o)
        return o

    def summary(self):
        paid = [o for o in self.orders if o.closed]
        return {"orders": len(paid), "revenue": round(sum(o.total() for o in paid), 2)}

if __name__ == "__main__":
    d = Day()
    o = d.open_order(4, {"burrito": (2, 12.5), "horchata": (2, 3.0)})
    o.closed = True
    print(d.summary())

